const body = $input.first().json.body || $input.first().json;
const cve = body.cve || 'no CVE ID given';
const severity = (body.severity || 'unknown').toUpperCase();
const desc = body.description || '(no description provided)';
const hosts = Array.isArray(body.affected_hosts) ? body.affected_hosts : [];
const triggerPatch = body.trigger_patch === true;

const text = `⚠️ ZERO-DAY PATCH WARNING [${severity}]\n${cve}\n${desc}\n\nAffected: ${hosts.length ? hosts.join(', ') : '(none listed)'}\n${triggerPatch ? 'Immediate patch runs are being triggered now for the listed hosts (snapshot-backed, auto-rollback on failure).' : 'No automatic patch triggered — review and patch manually via rolling_update.yml.'}`;
const txn_id = 'zeroday-' + Date.now();

return [{
  json: {
    txn_id,
    matrixPayload: { msgtype: 'm.text', body: text },
    hosts,
    triggerPatch
  }
}];
